"use client";
/* eslint-disable */
// NURA — Body Scan hero. Sage point-cloud human with a sweeping scan ring.
// Self-contained: model data is embedded; only dependency is "three".
import { useRef, useEffect } from "react";
import * as THREE from "three";

const RING = 1.414;
const POSITIONS_B64 = "";
const COLORS_B64 = "";

function b64f32(b: string): Float32Array {
  const s = atob(b), n = s.length, u = new Uint8Array(n);
  for (let i = 0; i < n; i++) u[i] = s.charCodeAt(i);
  return new Float32Array(u.buffer);
}

type Props = {
  className?: string;
  autoRotate?: boolean;   // slow idle spin (default true)
  interactive?: boolean;  // drag to rotate (default true)
  look?: "scan" | "glow" | "wire"; // default "scan"
};

export default function BodyScan({
  className,
  autoRotate = true,
  interactive = true,
  look = "scan",
}: Props) {
  const mountRef = useRef<HTMLDivElement | null>(null);

  useEffect(() => {
    const mount = mountRef.current;
    if (!mount) return;

    const SAGE = 0x9bb0a5, OFFWHITE = 0xebe6d8;
    const canvas = document.createElement("canvas");
    canvas.style.display = "block";
    canvas.style.width = "100%";
    canvas.style.height = "100%";
    canvas.style.touchAction = "none";
    if (interactive) canvas.style.cursor = "grab";
    mount.appendChild(canvas);

    const renderer = new THREE.WebGLRenderer({ canvas, antialias: true, alpha: true });
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));

    const scene = new THREE.Scene();
    const camera = new THREE.PerspectiveCamera(42, 1, 0.1, 200);

    // soft round sprite for each point
    function makeSprite() {
      const s = 64, cv = document.createElement("canvas");
      cv.width = cv.height = s;
      const x = cv.getContext("2d")!;
      const g = x.createRadialGradient(s / 2, s / 2, 0, s / 2, s / 2, s / 2);
      g.addColorStop(0, "rgba(255,255,255,1)");
      g.addColorStop(0.35, "rgba(255,255,255,.55)");
      g.addColorStop(1, "rgba(255,255,255,0)");
      x.fillStyle = g; x.fillRect(0, 0, s, s);
      return new THREE.CanvasTexture(cv);
    }
    const sprite = makeSprite();

    const positions = b64f32(POSITIONS_B64);
    const colors = b64f32(COLORS_B64);
    const geo = new THREE.BufferGeometry();
    geo.setAttribute("position", new THREE.BufferAttribute(positions, 3));
    geo.setAttribute("color", new THREE.BufferAttribute(colors, 3));

    const sizes = { scan: 0.046, glow: 0.066, wire: 0.028 } as const;
    const opac = { scan: 0.96, glow: 1.0, wire: 0.85 } as const;
    const bodyMat = new THREE.PointsMaterial({
      size: sizes[look], map: sprite, vertexColors: true, transparent: true,
      opacity: opac[look], blending: THREE.AdditiveBlending, depthWrite: false, sizeAttenuation: true,
    });
    const haloMat = bodyMat.clone(); haloMat.size = 0.13; haloMat.opacity = 0.1;
    const body = new THREE.Points(geo, bodyMat);
    const halo = new THREE.Points(geo, haloMat); halo.visible = look === "glow";
    const group = new THREE.Group(); group.add(body); group.add(halo); scene.add(group);

    const ring = new THREE.Mesh(
      new THREE.TorusGeometry(RING, 0.014, 8, 160),
      new THREE.MeshBasicMaterial({ color: OFFWHITE, transparent: true, opacity: 0.85, blending: THREE.AdditiveBlending, depthWrite: false })
    );
    ring.rotation.x = Math.PI / 2; scene.add(ring);
    const ringGlow = new THREE.Mesh(
      new THREE.TorusGeometry(RING, 0.11, 8, 160),
      new THREE.MeshBasicMaterial({ color: "var(--nura-accent-text)", transparent: true, opacity: 0.18, blending: THREE.AdditiveBlending, depthWrite: false })
    );
    ringGlow.rotation.x = Math.PI / 2; scene.add(ringGlow);

    const ambN = 320, amb = new Float32Array(ambN * 3);
    for (let i = 0; i < ambN; i++) {
      amb[i * 3] = (Math.random() - 0.5) * 16;
      amb[i * 3 + 1] = (Math.random() - 0.5) * 12;
      amb[i * 3 + 2] = (Math.random() - 0.5) * 9;
    }
    const ambGeo = new THREE.BufferGeometry();
    ambGeo.setAttribute("position", new THREE.BufferAttribute(amb, 3));
    const ambient = new THREE.Points(ambGeo, new THREE.PointsMaterial({
      color: "var(--nura-accent-text)", size: 0.04, map: sprite, transparent: true, opacity: 0.25, blending: THREE.AdditiveBlending, depthWrite: false,
    }));
    scene.add(ambient);

    let dragging = false, lastX = 0, vel = 0, rot = 0;
    const onDown = (e: PointerEvent) => { if (!interactive) return; dragging = true; lastX = e.clientX; };
    const onMove = (e: PointerEvent) => { if (!dragging) return; vel += (e.clientX - lastX) * 0.0008; lastX = e.clientX; };
    const onUp = () => { dragging = false; };
    canvas.addEventListener("pointerdown", onDown);
    window.addEventListener("pointermove", onMove);
    window.addEventListener("pointerup", onUp);

    function resize() {
      const w = mount!.clientWidth || 1, h = mount!.clientHeight || 1;
      renderer.setSize(w, h, false);
      camera.aspect = w / h;
      const vt = Math.tan((camera.fov * Math.PI) / 360);
      const z = Math.max(3.7 / vt, 1.7 / (vt * camera.aspect)) * 1.05;
      camera.position.set(0, 0.1, z);
      camera.lookAt(0, 0, 0);
      camera.updateProjectionMatrix();
    }
    const ro = new ResizeObserver(resize);
    ro.observe(mount);
    resize();

    const clock = new THREE.Clock();
    let raf = 0;
    function animate() {
      const t = clock.getElapsedTime();
      rot += (autoRotate ? 0.0025 : 0) + vel; vel *= 0.94;
      group.rotation.y = rot;
      const sy = Math.sin(t * 0.6) * 3.2 + 0.1;
      ring.position.y = sy; ringGlow.position.y = sy;
      (ringGlow.material as THREE.MeshBasicMaterial).opacity = 0.12 + 0.12 * (0.5 + 0.5 * Math.sin(t * 0.6));
      ambient.rotation.y = -t * 0.02;
      renderer.render(scene, camera);
      raf = requestAnimationFrame(animate);
    }
    animate();

    return () => {
      cancelAnimationFrame(raf);
      ro.disconnect();
      canvas.removeEventListener("pointerdown", onDown);
      window.removeEventListener("pointermove", onMove);
      window.removeEventListener("pointerup", onUp);
      geo.dispose(); bodyMat.dispose(); haloMat.dispose();
      ring.geometry.dispose(); (ring.material as THREE.Material).dispose();
      ringGlow.geometry.dispose(); (ringGlow.material as THREE.Material).dispose();
      ambGeo.dispose(); sprite.dispose();
      renderer.dispose();
      if (canvas.parentNode) canvas.parentNode.removeChild(canvas);
    };
  }, [autoRotate, interactive, look]);

  return <div ref={mountRef} className={className} style={{ width: "100%", height: "100%" }} />;
}
